static size_t mla_basis(BnGPUBackend*g,const BnBackendBF16MLAWeights*w,const char*directory){
 size_t total=0;for(int which=0;which<2;++which){int cols=which?w->kv_rank:w->key_dim,rows=which?w->value_dim:w->kv_rank;size_t nx=(size_t)cols*w->heads*cols,ny=(size_t)cols*w->heads*rows;uint16_t*x=calloc(nx,2);assert(x);for(int t=0;t<cols;++t)for(int h=0;h<w->heads;++h)x[((size_t)t*w->heads+h)*cols+t]=0x3f80;
  BnBackendSession*s=bn_backend_session_create(),*other=bn_backend_session_create();assert(s&&other);void*r=bn_gpu_backend_resident_request(g,s),*peer=bn_gpu_backend_resident_request(g,other);assert(!g->linear_bf16_reserve(g->ctx,r,0));BnGPUHeadLinearBF16ResidentPlan p={.n_tokens=cols,.heads=w->heads,.rows=rows,.cols=cols,.weight=which?w->value:w->key,.x=alloc(g,r,BN_GGUF_TENSOR_BF16,nx,x),.out=alloc(g,r,BN_GGUF_TENSOR_BF16,ny,NULL)};assert(!g->head_linear_bf16_resident(g->ctx,r,&p));total+=check(g,r,p.out,directory,which?"value-basis":"key-basis");BnGPUHeadLinearBF16ResidentPlan b;
#define BAD(change) do{b=p;change;assert(g->head_linear_bf16_resident(g->ctx,r,&b)==-1);}while(0)
  BAD(b.n_tokens=0);BAD(b.heads=0);BAD(b.rows++);BAD(b.cols++);BAD(b.x.count--);BAD(b.out=p.x);BAD(b.x.request=peer);BAD(b.weight=w->q_norm);BAD(b.x.offset=SIZE_MAX);
#undef BAD
  check(g,r,p.out,directory,which?"value-basis":"key-basis");bn_backend_session_free(other);bn_backend_session_free(s);free(x);
 }return total;
}
