  BnTransformerBF16MLAOutputPlan o={.weights=&w,.layer=3,.n_tokens=nt,.context=alloc(g,r,BN_GGUF_TENSOR_BF16,n*w.heads*w.kv_rank,context),.values=alloc(g,r,BN_GGUF_TENSOR_BF16,n*w.heads*w.value_dim,NULL),.out=alloc(g,r,BN_GGUF_TENSOR_BF16,n*w.dim,NULL)};assert(!bn_transformer_bf16_mla_output(r,&o));count+=check(g,r,o.values,dir,"values");count+=check(g,r,o.out,dir,"out");check(g,r,o.context,dir,"context");bn_backend_session_free(s);free(x);free(context);printf("case%d MLA projection PASSED tokens%d\n",ci,nt);fflush(stdout);
